package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type OrderRec struct {
	OrId    string
	OrStat  string
	OrQty   int64
	OrPrice decimal.Decimal
}

var WsEofFlag string = "N"
var WsTotal decimal.Decimal = decimal.NewFromInt(0)
var WsGrand decimal.Decimal = decimal.NewFromInt(0)
var WsNewCount int64 = 0
var WsShipCount int64 = 0
var WsCancelCount int64 = 0
var WsInvalid int64 = 0
var WsBadQty int64 = 0
var WsQtyEd string
var WsPriceEd string
var WsTotalEd string
var WsGrandEd string

var OrderRecVar OrderRec

var orderFile *os.File
var orderReader *bufio.Scanner
var orderAtEnd bool

func formatZZ9(v int64) string {
	return formatEditedInt(v, "ZZ9")
}
func formatZZZZ9_99_pic8(v decimal.Decimal) string {
	// PIC Z,ZZ9.99 len 8
	return formatEditedDecimal(v, "Z,ZZ9.99")
}
func formatZZZZZZZZ9_99_pic13(v decimal.Decimal) string {
	return formatEditedDecimal(v, "ZZ,ZZZ,ZZ9.99")
}
func formatZZZZZZZZZZ9_99_pic16(v decimal.Decimal) string {
	return formatEditedDecimal(v, "Z,ZZZ,ZZZ,ZZ9.99")
}

func formatEditedInt(val int64, picture string) string {
	// Generic handler for ZZ9 etc via decimal
	d := decimal.NewFromInt(val)
	return formatEditedDecimal(d, picture)
}

func formatEditedDecimal(val decimal.Decimal, picture string) string {
	// picture contains Z , . 9
	// width = len(picture)
	// Determine number of decimal places: after '.'
	scale := 0
	dotIdx := strings.Index(picture, ".")
	if dotIdx >= 0 {
		scale = len(picture) - dotIdx - 1
	}
	// Truncate toward zero to scale? Moves to edited fields truncate? In COBOL MOVE truncates.
	// We'll truncate.
	trunc := val.Truncate(int32(scale))
	// For formatting, we need absolute? No, positive only here.
	// Get integer and fractional parts
	// Use string representation
	// Shift to integer
	shifted := trunc.Shift(int32(scale)) // val * 10^scale truncated
	// shifted is integer
	isNeg := shifted.IsNegative()
	if isNeg {
		shifted = shifted.Neg()
	}
	intPart := shifted.Div(decimal.NewFromInt(1).Shift(int32(scale))).Truncate(0)
	// Actually intPart = shifted / 10^scale integer division
	pow10 := decimal.NewFromInt(1).Shift(int32(scale))
	intPart = shifted.Div(pow10).Truncate(0)
	fracPart := shifted.Mod(pow10).Abs()

	// Number of integer digit placeholders: count of 9 and Z before dot
	intPic := picture
	if dotIdx >= 0 {
		intPic = picture[:dotIdx]
	}
	intSlots := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intSlots++
		} else if c == ',' {
			intSlots++ // comma occupies position but logic special? Actually comma counts as separator width 1
			// But number of digits that can appear is number of 9/Z. High-order drop should be based on digit slots.
		}
	}
	// Digit slots count
	digitSlots := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			digitSlots++
		}
	}
	_ = intSlots
	// Build integer digits string, zero padded to digitSlots, then drop high order if overflow
	intStrRaw := intPart.StringFixed(0) // no decimals
	// intStrRaw may be "0"
	if len(intStrRaw) > digitSlots {
		intStrRaw = intStrRaw[len(intStrRaw)-digitSlots:]
	} else if len(intStrRaw) < digitSlots {
		intStrRaw = strings.Repeat("0", digitSlots-len(intStrRaw)) + intStrRaw
	}
	// Now map intStrRaw digits onto picture positions from right to left
	// Build result for integer part (including commas)
	intPicRunes := []rune(intPic)
	resInt := make([]rune, len(intPicRunes))
	// index for intStrRaw from rightmost
	dIdx := len(intStrRaw) - 1
	for i := len(intPicRunes) - 1; i >= 0; i-- {
		ch := intPicRunes[i]
		if ch == 'Z' || ch == '9' {
			digit := intStrRaw[dIdx]
			dIdx--
			if ch == 'Z' {
				// will handle suppression later
				resInt[i] = rune(digit)
			} else {
				resInt[i] = rune(digit)
			}
		} else if ch == ',' {
			resInt[i] = ','
		}
	}
	// Apply Z suppression: leading zeros become spaces, and commas in suppressed zone become spaces
	// Find first non-zero digit position in terms of digit slots
	// We need to know which resInt positions correspond to digits
	// Suppression: scan from leftmost digit placeholder; if digit is '0' and no non-zero has been seen yet, replace with space
	// Also any comma that is in the suppressed region (i.e., all digit positions to its left have been suppressed and no non-zero yet) becomes space.
	// The Z rule: Z replaces leading zero with space. Commas inside suppressed zone also become spaces.
	// Implementation: iterate left to right over intPicRunes
	suppressing := true
	for i := 0; i < len(intPicRunes); i++ {
		ch := intPicRunes[i]
		if ch == 'Z' {
			if suppressing {
				if resInt[i] == '0' {
					resInt[i] = ' '
				} else {
					suppressing = false
				}
			}
		} else if ch == '9' {
			// 9 never suppressed, but it ends suppression for following? Actually 9 will show digit even if zero, and stops suppression for its position only
			// However suppression only applies to Z positions; once we hit a 9, suppression ends
			suppressing = false
		} else if ch == ',' {
			if suppressing {
				// check if any non-suppressed digit to left? Actually suppression still active, so comma becomes space
				resInt[i] = ' '
			} else {
				// need to check if all digits to left are spaces: then comma should remain? In COBOL, comma floats? But spec says commas inside suppressed zone also become spaces.
				// Our suppressing flag already tells if we've seen non-zero.
				// So keep comma
			}
		}
	}
	// For Z picture, if value is zero, the last Z before 9 handling: above will make all leading Z become spaces, leaving last digit as '0' if it's a 9, or space if it's Z? But ZZ9 with 0 => "  0"
	// Our logic: For "ZZ9", digitSlots=3, intStrRaw="000", resInt initially ['0','0','0'], iteration: i0 Z with '0' -> ' ', suppressing true, i1 Z with '0' -> ' ', i2 9 -> suppressing false, stays '0' => "  0" correct.
	// For "Z,ZZ9.99" etc works.

	intPartStr := string(resInt)

	if dotIdx >= 0 {
		fracStr := fracPart.StringFixed(0)
		// pad with leading zeros to scale
		if len(fracStr) < scale {
			fracStr = strings.Repeat("0", scale-len(fracStr)) + fracStr
		} else if len(fracStr) > scale {
			fracStr = fracStr[len(fracStr)-scale:]
		}
		result := intPartStr + "." + fracStr
		// Ensure total width == len(picture)
		// intPartStr already width len(intPic), plus 1 + scale = len(picture)
		if isNeg {
			// Not needed here but handle: place minus? COBOL would have separate sign, ignore
			result = "-" + result[1:]
		}
		return result
	}
	return intPartStr
}

func formatPIC99(v int64) string {
	s := fmt.Sprintf("%d", v)
	if len(s) > 2 {
		s = s[len(s)-2:]
	} else if len(s) < 2 {
		s = strings.Repeat("0", 2-len(s)) + s
	}
	return s
}

func truncateDecimal(v decimal.Decimal, scale int32) decimal.Decimal {
	return v.Truncate(scale)
}

func main() {
	// Open input.dat
	var err error
	orderFile, err = os.Open("input.dat")
	if err != nil {
		// If file not exists, treat as empty
		orderFile = nil
		orderAtEnd = true
	} else {
		defer orderFile.Close()
		orderReader = bufio.NewScanner(orderFile)
		orderAtEnd = false
	}

	MAINPARA()

}

func MAINPARA() {
	OPENINPUT()
	READPARA()
	for !INPUTDONE() {
		PROCESSPARA()
	}
	CLOSEFILE()
	SUMMARYPARA()
}

func OPENINPUT() {
	// already opened
}

func CLOSEFILE() {
	if orderFile != nil {
		orderFile.Close()
	}
}

func INPUTDONE() bool {
	return WsEofFlag == "Y"
}

func READPARA() {
	if orderAtEnd {
		WsEofFlag = "Y"
		return
	}
	if orderReader != nil && orderReader.Scan() {
		line := orderReader.Text()
		// Pad with spaces to 15
		if len(line) < 15 {
			line = line + strings.Repeat(" ", 15-len(line))
		} else if len(line) > 15 {
			line = line[:15]
		}
		OrderRecVar.OrId = line[0:5]
		OrderRecVar.OrStat = line[5:6]
		// QTY 9(3)
		qtyStr := line[6:9]
		qtyStr = strings.TrimSpace(qtyStr)
		if qtyStr == "" {
			OrderRecVar.OrQty = 0
		} else {
			var v int64
			fmt.Sscanf(qtyStr, "%d", &v)
			OrderRecVar.OrQty = v
		}
		priceStr := line[9:15]
		priceStr = strings.TrimSpace(priceStr)
		if priceStr == "" {
			priceStr = "0"
		}
		// digits only
		var n int64
		fmt.Sscanf(priceStr, "%d", &n)
		OrderRecVar.OrPrice = decimal.New(n, -2)
	} else {
		WsEofFlag = "Y"
	}
}

func PROCESSPARA() {
	WsTotal = decimal.NewFromInt(0)
	// EVALUATE TRUE
	if OrderRecVar.OrQty == 0 {
		WsBadQty = (WsBadQty + 1) % 100
		fmt.Printf("%s BAD QTY\n", OrderRecVar.OrId)
	} else if OrderRecVar.OrStat == "N" {
		// COMPUTE WS-TOTAL = OR-QTY * OR-PRICE
		qtyDec := decimal.NewFromInt(OrderRecVar.OrQty)
		comp := qtyDec.Mul(OrderRecVar.OrPrice)
		WsTotal = truncateDecimal(comp, 2)
		// overflow handling: PIC 9(8)V99 -> keep low-order digits
		// For this we need to keep value modulo 10^8? But values in test don't overflow; still implement
		WsTotal = keepLowOrder(WsTotal, 8, 2)
		WsNewCount = (WsNewCount + 1) % 100
		SHOWPARA()
	} else if OrderRecVar.OrStat == "S" {
		qtyDec := decimal.NewFromInt(OrderRecVar.OrQty)
		comp := qtyDec.Mul(OrderRecVar.OrPrice).Mul(decimal.NewFromFloat(1.05))
		// ROUNDED
		WsTotal = comp.Round(2)
		WsTotal = keepLowOrder(WsTotal, 8, 2)
		WsShipCount = (WsShipCount + 1) % 100
		SHOWPARA()
	} else if OrderRecVar.OrStat == "C" {
		WsCancelCount = (WsCancelCount + 1) % 100
		SHOWPARA()
	} else {
		WsInvalid = (WsInvalid + 1) % 100
		fmt.Printf("%s BAD STATUS %s\n", OrderRecVar.OrId, OrderRecVar.OrStat)
	}
	// ADD WS-TOTAL TO WS-GRAND
	WsGrand = WsGrand.Add(WsTotal)
	WsGrand = keepLowOrder(WsGrand, 10, 2)
	READPARA()
}

func keepLowOrder(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// Keep low-order digits that fit: modulo 10^(intDigits+scale) / 10^scale ?
	// Implement by modulo 10^intDigits for integer part.
	// If v negative, handle preserve sign
	sign := 1
	if v.IsNegative() {
		sign = -1
		v = v.Neg()
	}
	// v has scale 2, shift to integer
	shifted := v.Shift(scale) // integer
	modBase := decimal.NewFromInt(1).Shift(int32(intDigits + int(scale)))
	shifted = shifted.Mod(modBase)
	v2 := shifted.Shift(-scale)
	if sign == -1 {
		v2 = v2.Neg()
	}
	return v2
}

func SHOWPARA() {
	WsQtyEd = formatZZ9(OrderRecVar.OrQty)
	WsPriceEd = formatZZZZ9_99_pic8(OrderRecVar.OrPrice)
	WsTotalEd = formatZZZZZZZZ9_99_pic13(WsTotal)
	fmt.Printf("%s %s %s %s %s\n", OrderRecVar.OrId, OrderRecVar.OrStat, WsQtyEd, WsPriceEd, WsTotalEd)
}

func SUMMARYPARA() {
	WsGrandEd = formatZZZZZZZZZZ9_99_pic16(WsGrand)
	fmt.Printf("NEW: %s SHIPPED: %s CANCELLED: %s\n", formatPIC99(WsNewCount), formatPIC99(WsShipCount), formatPIC99(WsCancelCount))
	fmt.Printf("INVALID: %s BAD QTY: %s\n", formatPIC99(WsInvalid), formatPIC99(WsBadQty))
	fmt.Printf("GRAND TOTAL: %s\n", WsGrandEd)
}
